#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string modifyString(string s) {
        for (int i = 0; i < (int)s.size(); ++i) {
            if (s[i] != '?') continue;
            for (char c = 'a'; c <= 'c'; ++c) {
                if ((i == 0 || s[i - 1] != c) &&
                    (i + 1 == (int)s.size() || s[i + 1] != c)) {
                    s[i] = c; break;
                }
            }
        }
        return s;
    }
};
